const fs = require('fs');
const path = require('path');
const course = require('../content/resources/course.json');
const resources = require('../content/resources/catalog.json');
const { contentInfo, resourceLinks } = require('./generateResources');

const root = path.resolve(__dirname, '../..');
const marker =
  '// Generated by npm run contentgen:walkthroughs. Edit the walkthrough MDX and catalog.';

function validateWalkthroughs() {
  const catalog = require('../content/lesson-walkthroughs/catalog.json');
  require('./walkthroughCoverage').validateCoverage(
    catalog,
    course,
    require('../content/lesson-walkthroughs/coverage.json'),
  );
  const routes = new Set();
  const titles = new Set();
  const languages = new Set(
    resources.filter((item) => item.section === 'interview-prep').map((item) => item.slug),
  );
  const inventory = new Set(
    require('../utils/server/discovery')
      .publicPaths()
      .map((item) => item.path),
  );
  return catalog.map((page) => {
    const id = `${page.lesson}/${page.language}`;
    const route = `/course/${id}`;
    if (![page.lesson, page.language].every((part) => /^[a-z0-9-]+$/.test(part)))
      throw new Error(`Unsafe walkthrough route: ${id}`);
    if (routes.has(route)) throw new Error(`Duplicate walkthrough: ${id}`);
    routes.add(route);
    const lesson = course.lessons.find((item) => item.slug === page.lesson);
    if (!lesson || !languages.has(page.language))
      throw new Error(`Unpublished lesson or unknown language: ${id}`);
    if (!page.title || !page.description || titles.has(page.title))
      throw new Error(`Missing or duplicate walkthrough metadata: ${id}`);
    titles.add(page.title);
    const lessonRoot = path.join(root, 'src/content/lessons', page.lesson);
    const file = `${page.language}.mdx`;
    const solutionRoot = path.join(lessonRoot, 'Solution/code');
    if (
      !page.kind &&
      (!fs.existsSync(path.join(lessonRoot, 'UserAnswer', file)) ||
        !fs.existsSync(solutionRoot) ||
        !fs
          .readdirSync(solutionRoot)
          .some((variant) => fs.existsSync(path.join(solutionRoot, variant, file))))
    )
      throw new Error(`Missing starter/reference language: ${id}`);
    const source = fs.readFileSync(
      path.join(root, 'src/content/lesson-walkthroughs', `${id}.mdx`),
      'utf8',
    );
    const info = contentInfo(source);
    const prose = source.replace(/```[^\n]*\n[\s\S]*?```/g, '');
    if (/^# /m.test(prose) || /\b(TODO|TBD)\b/.test(prose) || /\blorem ipsum\b/i.test(prose))
      throw new Error(`Unfinished text or duplicate page title: ${id}`);
    if (
      info.words < 650 ||
      info.headings.length < 4 ||
      new Set(info.headings.map((h) => h.id)).size !== info.headings.length
    )
      throw new Error(
        `Review walkthrough substance and headings: ${id} (${info.words} prose words)`,
      );
    if (!source.includes('```' + page.language + '\n'))
      throw new Error(`Missing matching code example: ${id}`);
    for (const href of resourceLinks(source)) {
      if (href.startsWith('/') && !inventory.has(href.split(/[?#]/)[0]))
        throw new Error(`Broken walkthrough link ${href} in ${id}`);
    }
    return { page, info };
  });
}

function generate() {
  require('./composeWalkthroughs').compose();
  require('./composeFoundationWalkthroughs').compose();
  const pages = validateWalkthroughs();
  const destinations = new Set();
  for (const { page, info } of pages) {
    const id = `${page.lesson}/${page.language}`;
    const destination = path.join(root, 'src/pages/course', `${id}.tsx`);
    destinations.add(destination);
    fs.mkdirSync(path.dirname(destination), { recursive: true });
    fs.writeFileSync(
      destination,
      `${marker}\nimport * as React from 'react';\nimport LessonWalkthroughPage from 'components/pages/Resources/LessonWalkthroughPage';\nimport Content from 'content/lesson-walkthroughs/${id}.mdx';\n\nexport default function Page() {\n  return <LessonWalkthroughPage walkthrough={${JSON.stringify(
        page,
      )}} headings={${JSON.stringify(info.headings)}} minutes={${
        info.minutes
      }}><Content /></LessonWalkthroughPage>;\n}\n`,
    );
  }
  // Remove only routes owned by this generator when an editor unpublishes an entry.
  const courseRoot = path.join(root, 'src/pages/course');
  for (const folder of fs
    .readdirSync(courseRoot, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())) {
    for (const file of fs
      .readdirSync(path.join(courseRoot, folder.name))
      .filter((name) => name.endsWith('.tsx'))) {
      const destination = path.join(courseRoot, folder.name, file);
      if (!destinations.has(destination) && fs.readFileSync(destination, 'utf8').startsWith(marker))
        fs.unlinkSync(destination);
    }
  }
  console.log(
    `Generated ${pages.length} lesson walkthroughs; ${pages
      .reduce((sum, entry) => sum + entry.info.words, 0)
      .toLocaleString('en-US')} prose words.`,
  );
}

if (require.main === module) generate();
module.exports = { validateWalkthroughs, generate };
